INSERT INTO `privacy_policies` (`id`, `privacy_policy`, `created_at`, `updated_at`) VALUES
(1, '[{\"title\":\"Introduction to privacy policy\",\"paragraph\":\"Welcome to BLUEBELL GROUP! Your privacy is important to us. This Privacy Policy outlines the types of information we collect, how we use it, and the steps we take to ensure your information is protected.\"},{\"title\":\"Personal Information\",\"paragraph\":\"When you engage with BLUEBELL GROUP, we may collect personal information, including but not limited to your name, email address, phone number, business details, and payment information.\"},{\"title\":\"Usage Data\",\"paragraph\":\"We collect information on how you interact with BLUEBELL GROUP services, such as features used, pages visited, search queries, and device\\/browser information. This helps us improve your experience and optimize our platform.\"},{\"title\":\"Cookies and Tracking Technologies\",\"paragraph\":\"We use cookies and similar technologies to personalize your experience on our platform. These help remember your preferences, login details, and tailor content accordingly. You can manage your cookie preferences through your browser settings.\"},{\"title\":\"To Provide and Improve Our Services\",\"paragraph\":\"Your information helps us deliver, maintain, and improve our offerings. It also enables us to personalize your experience and provide customer support effectively.\"},{\"title\":\"Communication\",\"paragraph\":\"We may use your contact details to send updates, newsletters, service notifications, and promotional content. You can opt out of marketing communications at any time through the unsubscribe link or by contacting us.\"},{\"title\":\"Payment Processing\",\"paragraph\":\"Your payment details are used solely for completing transactions. We partner with reputable third-party payment processors who comply with industry-standard security protocols.\"},{\"title\":\"Third-Party Service Providers\",\"paragraph\":\"We may share your information with third-party partners who help us operate, manage, or improve BLUEBELL GROUP services. These partners are contractually required to keep your data secure and confidential.\"},{\"title\":\"Legal Requirements\",\"paragraph\":\"We may disclose your information to comply with legal obligations or respond to lawful requests, such as subpoenas or court orders.\"},{\"title\":\"Business Transfers\",\"paragraph\":\"In the event of a merger, acquisition, or sale of our assets, your information may be transferred as part of the business transaction. The new entity will uphold the commitments of this policy.\"},{\"title\":\"Data Security\",\"paragraph\":\"We take data security seriously. We implement industry-standard security measures to protect your personal information from unauthorized access, alteration, or loss.\"},{\"title\":\"Your Rights\",\"paragraph\":\"You have the right to access, update, or delete your personal information. You can manage your account settings or contact our support team to exercise these rights.\"},{\"title\":\"Children\'s Privacy\",\"paragraph\":\"BLUEBELL GROUP services are not intended for individuals under the age of 13. We do not knowingly collect information from children under 13. If such data is discovered, it will be promptly removed.\"},{\"title\":\"Changes to This Privacy Policy\",\"paragraph\":\"We may update this Privacy Policy periodically. When we do, we will revise the effective date and post the updated version on our website. Continued use of BLUEBELL GROUP services after changes implies acceptance of the revised policy.\"},{\"title\":\"Contact Us\",\"paragraph\":\"If you have any questions or concerns about this Privacy Policy, please contact us at:\\r\\n\\r\\nBLUEBELL GROUP\\r\\nSupport Team\\r\\nEmail: dashbhusan31@gmail.com\"}]', '2025-02-17 14:58:34', '2025-05-03 16:27:38');
